use strict;
use warnings;
use Test::More;
use Accounts;

{
    package RecordingDb;
    sub new { my ($class) = @_; return bless { calls => [] }, $class }
    sub selectall_arrayref {
        my ($self, $sql, $attributes, @bind) = @_;
        push @{ $self->{calls} }, [$sql, @bind];
        return [[25]];
    }
}

subtest benign_control => sub {
    my $dbh = RecordingDb->new;
    is_deeply(Accounts::balance($dbh, 'alice'), [[25]], 'returns the rows');
    is(scalar @{ $dbh->{calls} }, 1, 'issues one statement');
};

subtest security_binds_account => sub {
    my $dbh = RecordingDb->new;
    my $hostile = "alice' OR 1=1 --";
    Accounts::balance($dbh, $hostile);
    my ($sql, @bind) = @{ $dbh->{calls}[0] };
    ok(index($sql, $hostile) < 0, 'keeps the account out of the SQL');
    is_deeply(\@bind, [$hostile], 'binds the account');
};

done_testing();
